public int uniquePathsWithObstacles(int[][] grid) {
    int n = grid[0].length;
    int[] dp = new int[n];
    dp[0] = grid[0][0] == 0 ? 1 : 0;
    for (int[] row : grid)
        for (int j = 0; j < n; j++) {
            if (row[j] == 1) dp[j] = 0;
            else if (j > 0) dp[j] += dp[j - 1];
        }
    return dp[n - 1];
}

public int minPathSum(int[][] grid) {
    int n = grid[0].length;
    int[] dp = new int[n];
    dp[0] = grid[0][0];
    for (int j = 1; j < n; j++) dp[j] = dp[j - 1] + grid[0][j];
    for (int i = 1; i < grid.length; i++) {
        dp[0] += grid[i][0];
        for (int j = 1; j < n; j++)
            dp[j] = grid[i][j] + Math.min(dp[j], dp[j - 1]);
    }
    return dp[n - 1];
}

public int calculateMinimumHP(int[][] d) {
    int m = d.length, n = d[0].length;
    int[][] dp = new int[m + 1][n + 1];
    for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE);
    dp[m][n - 1] = dp[m - 1][n] = 1;                 // just past the exit
    for (int i = m - 1; i >= 0; i--)
        for (int j = n - 1; j >= 0; j--) {
            int need = Math.min(dp[i + 1][j], dp[i][j + 1]) - d[i][j];
            dp[i][j] = Math.max(1, need);
        }
    return dp[0][0];
}

public int cherryPickup(int[][] grid) {
    int n = grid.length;
    Integer[][][] memo = new Integer[n][n][n];
    return Math.max(0, dp(grid, 0, 0, 0, memo, n));
}
private int dp(int[][] grid, int r1, int c1, int r2, Integer[][][] memo, int n) {
    int c2 = r1 + c1 - r2;
    if (r1 >= n || c1 >= n || r2 >= n || c2 >= n
            || grid[r1][c1] == -1 || grid[r2][c2] == -1)
        return Integer.MIN_VALUE;
    if (r1 == n - 1 && c1 == n - 1) return grid[r1][c1];
    if (memo[r1][c1][r2] != null) return memo[r1][c1][r2];
    int cherries = grid[r1][c1];
    if (r1 != r2 || c1 != c2) cherries += grid[r2][c2];
    int best = Math.max(
        Math.max(dp(grid, r1 + 1, c1, r2 + 1, memo, n), dp(grid, r1 + 1, c1, r2, memo, n)),
        Math.max(dp(grid, r1, c1 + 1, r2 + 1, memo, n), dp(grid, r1, c1 + 1, r2, memo, n)));
    if (best == Integer.MIN_VALUE) return memo[r1][c1][r2] = Integer.MIN_VALUE;
    return memo[r1][c1][r2] = cherries + best;
}

public int cherryPickup(int[][] grid) {
    int cols = grid[0].length;
    Integer[][][] memo = new Integer[grid.length][cols][cols];
    return dp(grid, 0, 0, cols - 1, memo);
}
private int dp(int[][] grid, int r, int c1, int c2, Integer[][][] memo) {
    int cols = grid[0].length;
    if (c1 < 0 || c1 >= cols || c2 < 0 || c2 >= cols) return Integer.MIN_VALUE;
    if (memo[r][c1][c2] != null) return memo[r][c1][c2];
    int cherries = grid[r][c1];
    if (c1 != c2) cherries += grid[r][c2];
    if (r < grid.length - 1) {
        int best = Integer.MIN_VALUE;
        for (int nc1 = c1 - 1; nc1 <= c1 + 1; nc1++)
            for (int nc2 = c2 - 1; nc2 <= c2 + 1; nc2++)
                best = Math.max(best, dp(grid, r + 1, nc1, nc2, memo));
        cherries += best;
    }
    return memo[r][c1][c2] = cherries;
}

public int maximalSquare(char[][] matrix) {
    int m = matrix.length, n = matrix[0].length, best = 0;
    int[] dp = new int[n + 1];
    for (int i = 1; i <= m; i++) {
        int prev = 0;                       // dp[i-1][j-1]
        for (int j = 1; j <= n; j++) {
            int tmp = dp[j];
            if (matrix[i - 1][j - 1] == '1') {
                dp[j] = Math.min(Math.min(dp[j], dp[j - 1]), prev) + 1;
                best = Math.max(best, dp[j]);
            } else dp[j] = 0;
            prev = tmp;
        }
    }
    return best * best;
}

public int[] pathsWithMaxScore(List<String> board) {
    int MOD = 1_000_000_007;
    int n = board.size();
    int[][] maxSum = new int[n + 1][n + 1];
    int[][] cnt = new int[n + 1][n + 1];
    for (int[] row : maxSum) Arrays.fill(row, -1);
    maxSum[1][1] = 0; cnt[1][1] = 1;              // 'E' at (0,0)
    int[][] dirs = {{-1, 0}, {0, -1}, {-1, -1}};
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++) {
            char ch = board.get(i - 1).charAt(j - 1);
            if (ch == 'X' || ch == 'E') continue;
            int best = -1, ways = 0;
            for (int[] d : dirs) {
                int pi = i + d[0], pj = j + d[1];
                if (maxSum[pi][pj] < 0) continue;
                if (maxSum[pi][pj] > best) { best = maxSum[pi][pj]; ways = cnt[pi][pj]; }
                else if (maxSum[pi][pj] == best) ways = (ways + cnt[pi][pj]) % MOD;
            }
            if (best < 0) continue;
            int val = ch == 'S' ? 0 : ch - '0';
            maxSum[i][j] = best + val;
            cnt[i][j] = ways;
        }
    if (maxSum[n][n] < 0) return new int[]{0, 0};
    return new int[]{maxSum[n][n], cnt[n][n]};
}

public int minDistance(String a, String b) {
    int m = a.length(), n = b.length();
    int[] dp = new int[n + 1];
    for (int j = 0; j <= n; j++) dp[j] = j;
    for (int i = 1; i <= m; i++) {
        int prev = dp[0];                 // dp[i-1][j-1]
        dp[0] = i;
        for (int j = 1; j <= n; j++) {
            int tmp = dp[j];
            if (a.charAt(i - 1) == b.charAt(j - 1)) dp[j] = prev;
            else dp[j] = 1 + Math.min(prev, Math.min(dp[j], dp[j - 1]));
            prev = tmp;
        }
    }
    return dp[n];
}

public int longestCommonSubsequence(String text1, String text2) {
    int m = text1.length(), n = text2.length();
    int[] dp = new int[n + 1];
    for (int i = 1; i <= m; i++) {
        int prev = 0;                     // dp[i-1][j-1]
        for (int j = 1; j <= n; j++) {
            int tmp = dp[j];
            if (text1.charAt(i - 1) == text2.charAt(j - 1)) dp[j] = prev + 1;
            else dp[j] = Math.max(dp[j], dp[j - 1]);
            prev = tmp;
        }
    }
    return dp[n];
}

public int numDistinct(String s, String t) {
    int n = t.length();
    long[] dp = new long[n + 1];
    dp[0] = 1;
    for (int i = 0; i < s.length(); i++)
        for (int j = n; j >= 1; j--)
            if (s.charAt(i) == t.charAt(j - 1)) dp[j] += dp[j - 1];
    return (int) dp[n];
}

public boolean isInterleave(String s1, String s2, String s3) {
    int m = s1.length(), n = s2.length();
    if (m + n != s3.length()) return false;
    boolean[] dp = new boolean[n + 1];
    dp[0] = true;
    for (int j = 1; j <= n; j++)
        dp[j] = dp[j - 1] && s2.charAt(j - 1) == s3.charAt(j - 1);
    for (int i = 1; i <= m; i++) {
        dp[0] = dp[0] && s1.charAt(i - 1) == s3.charAt(i - 1);
        for (int j = 1; j <= n; j++)
            dp[j] = (dp[j] && s1.charAt(i - 1) == s3.charAt(i + j - 1))
                 || (dp[j - 1] && s2.charAt(j - 1) == s3.charAt(i + j - 1));
    }
    return dp[n];
}

public boolean isMatch(String s, String p) {
    int m = s.length(), n = p.length();
    boolean[][] dp = new boolean[m + 1][n + 1];
    dp[0][0] = true;
    for (int j = 1; j <= n; j++)
        if (p.charAt(j - 1) == '*') dp[0][j] = dp[0][j - 2];
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++) {
            char pc = p.charAt(j - 1);
            if (pc == '*') {
                dp[i][j] = dp[i][j - 2];                 // zero of preceding
                char prev = p.charAt(j - 2);
                if (prev == '.' || prev == s.charAt(i - 1))
                    dp[i][j] = dp[i][j] || dp[i - 1][j]; // one more of preceding
            } else if (pc == '.' || pc == s.charAt(i - 1)) {
                dp[i][j] = dp[i - 1][j - 1];
            }
        }
    return dp[m][n];
}

public boolean isMatch(String s, String p) {
    int m = s.length(), n = p.length();
    boolean[][] dp = new boolean[m + 1][n + 1];
    dp[0][0] = true;
    for (int j = 1; j <= n; j++)
        if (p.charAt(j - 1) == '*') dp[0][j] = dp[0][j - 1];
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++) {
            char pc = p.charAt(j - 1);
            if (pc == '*') dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            else if (pc == '?' || pc == s.charAt(i - 1)) dp[i][j] = dp[i - 1][j - 1];
        }
    return dp[m][n];
}

public String shortestCommonSupersequence(String str1, String str2) {
    int m = str1.length(), n = str2.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++)
            dp[i][j] = str1.charAt(i - 1) == str2.charAt(j - 1)
                ? dp[i - 1][j - 1] + 1
                : Math.max(dp[i - 1][j], dp[i][j - 1]);
    StringBuilder sb = new StringBuilder();
    int i = m, j = n;
    while (i > 0 && j > 0) {
        if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
            sb.append(str1.charAt(i - 1)); i--; j--;
        } else if (dp[i - 1][j] >= dp[i][j - 1]) {
            sb.append(str1.charAt(i - 1)); i--;
        } else {
            sb.append(str2.charAt(j - 1)); j--;
        }
    }
    while (i > 0) sb.append(str1.charAt(--i));
    while (j > 0) sb.append(str2.charAt(--j));
    return sb.reverse().toString();
}

public int longestPalindromeSubseq(String s) {
    int n = s.length();
    int[][] dp = new int[n][n];
    for (int i = n - 1; i >= 0; i--) {
        dp[i][i] = 1;
        for (int j = i + 1; j < n; j++) {
            if (s.charAt(i) == s.charAt(j)) dp[i][j] = dp[i + 1][j - 1] + 2;
            else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
        }
    }
    return dp[0][n - 1];
}

public boolean isScramble(String s1, String s2) {
    if (s1.length() != s2.length()) return false;
    return solve(s1, s2, new HashMap<>());
}
private boolean solve(String s1, String s2, Map<String, Boolean> memo) {
    if (s1.equals(s2)) return true;
    String key = s1 + "#" + s2;
    if (memo.containsKey(key)) return memo.get(key);
    int[] cnt = new int[26];
    for (int i = 0; i < s1.length(); i++) {
        cnt[s1.charAt(i) - 'a']++;
        cnt[s2.charAt(i) - 'a']--;
    }
    for (int c : cnt) if (c != 0) { memo.put(key, false); return false; }
    int n = s1.length();
    boolean res = false;
    for (int i = 1; i < n && !res; i++) {
        if (solve(s1.substring(0, i), s2.substring(0, i), memo)
                && solve(s1.substring(i), s2.substring(i), memo)) res = true;
        else if (solve(s1.substring(0, i), s2.substring(n - i), memo)
                && solve(s1.substring(i), s2.substring(0, n - i), memo)) res = true;
    }
    memo.put(key, res);
    return res;
}
